def semver_sort(versions):
    def parse_version(version):
        # Split by '+' to separate build metadata
        version_part, _, _ = version.partition('+')

        # Split by '-' to separate pre-release
        if '-' in version_part:
            base_part, _, prerelease = version_part.partition('-')
        else:
            base_part = version_part
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = base_part.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        prerelease_identifiers = []
        if prerelease:
            for identifier in prerelease.split('.'):
                if identifier.isdigit():
                    prerelease_identifiers.append((0, int(identifier)))
                else:
                    prerelease_identifiers.append((1, identifier))

        return (major, minor, patch, prerelease_identifiers)

    def sort_key(item):
        index, version = item
        major, minor, patch, prerelease_identifiers = parse_version(version)
        # Versions with pre-release sort before versions without
        # (0, prerelease_identifiers) means it has pre-release
        # (1,) means it doesn't have pre-release
        has_prerelease = (0,) if prerelease_identifiers else (1,)
        return (major, minor, patch, has_prerelease, prerelease_identifiers, index)

    indexed_versions = list(enumerate(versions))
    sorted_versions = sorted(indexed_versions, key=sort_key)
    return [version for _, version in sorted_versions]

